            'WINDOWS_TRANSPORT_HARNESS_SHA256 = (\n    "'
            + namespace["WINDOWS_TRANSPORT_HARNESS_SHA256"]
            + '"\n)'
        ).encode()
        new_slot = ('WINDOWS_TRANSPORT_HARNESS_SHA256 = (\n    "' + new_digest + '"\n)').encode()
